```csharp
using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // ─── CalculateTotal: DataRow for inline test cases ───

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 2, 0.10, 22.00, DisplayName = "Two items, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice")]
    [DataRow(10.00, -1, 0.10, "quantity")]
    [DataRow(10.00, 1, -0.01, "taxRate")]
    [DataRow(10.00, 1, 1.01, "taxRate")]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRange(
        double unitPrice, int quantity, double taxRate, string expectedParam)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParam, ex.ParamName);
    }

    // ─── ApplyDiscount: DynamicData with ValueTuples for type safety ───

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, decimal discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10m, 90m),
        (200m, 25m, 150m),
        (50m, 0m, 50m),
        (80m, 100m, 0m),
        (99.99m, 50m, 49.995m),
    ];

    [TestMethod]
    [DataRow(100.00, -1.0)]
    [DataRow(100.00, 101.0)]
    public void ApplyDiscount_WithInvalidPercent_ThrowsArgumentOutOfRange(
        double price, double discountPercent)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent));

        Assert.AreEqual("discountPercent", ex.ParamName);
    }

    // ─── FormatPrice: DataRow for string output ───

    [TestMethod]
    [DataRow(19.99, "$", "$19.99")]
    [DataRow(5.5, "€", "€5.50")]
    [DataRow(0.0, "$", "$0.00")]
    public void FormatPrice_ReturnsFormattedString(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}
```

**Key patterns demonstrated:**

| Technique | When to use |
|-----------|-------------|
| `[DataRow]` | Simple inline primitives (`double`/`int`/`string`) |
| `[DynamicData]` + ValueTuples | Complex types or `decimal` (not allowed in attributes) |
| `Assert.ThrowsExactly<T>` | Validates exception type + param name |
| `DisplayName` | Makes Test Explorer output readable |

**Notes:**
- `[DataRow]` can't use `decimal` literals, so we pass `double` and cast — or use `[DynamicData]` for exact decimal precision (as shown in `ApplyDiscount`).
- Test class is `sealed` per modern MSTest conventions.
- `[DataTestMethod]` is not needed — `[TestMethod]` handles data rows since MSTest 3.x.
